    [211419] = { enName = "Handful of Shifting Scales", itName = "Scaglie del Sogno", enDescription = "These curious scales seem to shimmer slightly, as if they are not fully corporeal. There is clearly wonderous magic at play here... if only you could find someone who knows more about them.", description = "Queste scaglie curiose scintillano debolmente, come se non fossero del tutto corporee. È chiaramente all’opera una magia meravigliosa… se solo trovassi qualcuno che ne sa di più." },
    [211427] = { enName = "Soul Vessel", enDescription = "Traps demon souls and siphons them for power.", description = "Intrappola le anime dei demoni e ne assorbe il potere." },
    [211472] = { enName = "Libram of Banishment", enDescription = "Learn a new ability after casting Turn Undead on 5 enemies, and slaying them with Exorcism.", description = "Apprendi una nuova abilità dopo aver lanciato Scaccia Non Morti su 5 nemici e averli uccisi con Esorcismo." },
    [211487] = { enName = "Demolition Explosives", enDescription = "Only seems useful for clearing out debris and rubble.", description = "Sembra utile solo per rimuovere detriti e macerie." },
    [211527] = { enName = "Cozy Sleeping Bag", enDescription = "Old, but still good", description = "Vecchio, ma ancora valido." },
    [211779] = { enName = "Comprehension Charm", enDescription = "Aids the translation of scrolls and spell notes.", description = "Aiuta a tradurre pergamene e appunti sugli incantesimi." },
    [211799] = { enName = "Sack of Stolen Goods", itName = "Borsa di Spoglie", enDescription = "Likely taken from the cathedral when Ada ran away.", description = "Probabilmente è stato preso dalla cattedrale quando Ada è scappata." },
    [211809] = { enName = "Comprehension Primer", enDescription = "Aids in translation of elementary spell notes.", description = "Aiuta a tradurre appunti elementari sugli incantesimi." },
    [211815] = { enName = "Silverwing Battle Hymn", itName = "Pergamena della Forza", enDescription = "A stirring arrangement to rally morale before battle.", description = "Un arrangiamento coinvolgente per risollevare il morale prima della battaglia." },
    [211816] = { enName = "Warsong Battle Drum", itName = "Pergamena della Forza", enDescription = "Drums of war to prepare for battle.", description = "Tamburi di guerra per prepararsi alla battaglia." },
    [211845] = { enName = "Blackfathom Sharpening Stone", itName = "Pietra da Affilatura Elementale", enDescription = "These mysterious enchanted stones seem to glow more brightly the deeper you descend into Blackfathom.", description = "Queste pietre incantate e misteriose sembrano brillare sempre di più man mano che si scende nelle profondità di Fondocupo." },
    [212230] = { enName = "Schematic: Soul Vessel", itName = "Schema: Bom-Bot", enDescription = "Teaches you how to make a Soul Vessel.", description = "Ti insegna a creare un Ricettacolo dell’Anima." },
    [213127] = { enName = "Partial Mystical Notes", itName = "Partial Mystical Notes", enDescription = "\"Eggs\" can just about be made out in the unreadable scrawl.", description = "Nella grafia illeggibile si riesce a distinguere a malapena la parola «uova»." },
    [213165] = { enName = "Basilisks: Should Petrification be Feared?", itName = "Ricetta: Stufato delle Marche Occidentali", enDescription = "Attempted research on the use of basilisk parts as reagents. A fine addition to any library's collection.", description = "Ricerche sull’uso di parti di basilisco come reagenti. Un’ottima aggiunta alla collezione di qualsiasi biblioteca." },
    [213370] = { enName = "Irradiated Leather Scraps", itName = "Frammenti di Cuoio Leggero", enDescription = "A skilled leatherworker may be able to fashion this into something useful.", description = "Un conciatore esperto potrebbe ricavarne qualcosa di utile." },
    [213371] = { enName = "Crate of Tainted Gniodine Solution", itName = "Fogliargenta", enDescription = "A skilled alchemist may be able to fashion this into something useful.", description = "Un alchimista esperto potrebbe ricavarne qualcosa di utile." },
    [213373] = { enName = "Reflective Scrapmetal", itName = "Minerale di Verargento", enDescription = "A skilled blacksmith may be able to fashion this into something usable.", description = "Un fabbro esperto potrebbe ricavarne qualcosa di utile." },
    [213378] = { enName = "Unstable Microfilament", itName = "Filo di Seta", enDescription = "A skilled tailor may be able to fashion this into something useful.", description = "Un sarto esperto potrebbe ricavarne qualcosa di utile." },
    [213381] = { enName = "Pile of Tarnished Gears", itName = "Fogliargenta", enDescription = "A skilled engineer may be able to fashion this into something useful.", description = "Un ingegnere esperto potrebbe ricavarne qualcosa di utile." },
    [213452] = { enName = "Dormant Holy Rune", enDescription = "First, you must lay down your life for another. Then, before your spirit departs, have your salvation returned in kind.", description = "Per prima cosa, devi sacrificare la tua vita per un altro. Poi, prima che il tuo spirito se ne vada, ricevi in cambio la tua salvezza." },
    [213513] = { enName = "Libram of Deliverance", enDescription = "Learn a new ability after using Blessing of Freedom to free others from movement impairing effects 5 times.", description = "Apprendi una nuova abilità dopo aver usato Benedizione della Libertà per liberare altri dagli effetti che limitano i movimenti, per 5 volte." },
    [213526] = { enName = "Hybrid Haunch", enDescription = "Tastes like beef *and* chicken.", description = "Ha il sapore di manzo *e* pollo." },
    [213527] = { enName = "Smuggler's Spice Blend", enDescription = "The crown jewel of any ship's galley. Could make a boot taste good.", description = "Il fiore all’occhiello della cambusa di ogni nave. Può rendere gustoso anche uno stivale." },
    [213528] = { enName = "Balmy Brew", enDescription = "Not exactly a 'cold one' per-se", description = "Non è proprio una «birra ghiacciata»." },
    [213529] = { enName = "Viscous Venom", enDescription = "Eats through swamp critters like they're nothing. Great for marinades!", description = "Digerisce le creature delle paludi come niente. Ottimo per le marinate!" },
    [213552] = { enName = "Tear of Theradras", enDescription = "Hoarded and closely guarded by the Gelkis centaur tribe, these are said to grant their wielder the protection of the earthen spirits.", description = "Custodite gelosamente dalla tribù dei centauri Gelkis, si dice che queste lacrime conferiscano a chi le impugna la protezione degli spiriti della terra." },
    [213553] = { enName = "Tear of Theradras", enDescription = "Hoarded and closely guarded by the Gelkis centaur tribe, these are said to grant their weilder the protection of the earthen spirits.", description = "Custodite gelosamente dalla tribù dei centauri Gelkis, si dice che queste lacrime conferiscano a chi le impugna la protezione degli spiriti della terra." },
    [213554] = { enName = "Vial of Crystal Water", enDescription = "The water is so crystal clear that the vial seems empty.", description = "L’acqua è così limpida che la fiala sembra vuota." },
    [213558] = { enName = "Elemental Salve", enDescription = "A potent salve capable of cleansing deep corruption.", description = "Un unguento potente, capace di purificare una corruzione profonda." },
    [213583] = { enName = "Brimstone Carving", enDescription = "It appears the previous owner played with fire one too few times.", description = "Sembra che il precedente proprietario abbia giocato col fuoco una volta di troppo." },
    [213594] = { enName = "Idol of the Heckler", enDescription = "Taunt 2 or more enemies with Challenging Roar, and kill at least one of them. After 3 kills, use this idol to learn a new ability.", description = "Provoca 2 o più nemici con Ruggito Provocatorio e uccidine almeno uno. Dopo 3 uccisioni, usa questo idolo per apprendere una nuova abilità." },
    [215138] = { enName = "Formula: Enchant Chest - Retricutioner", itName = "Formula: Incanta Arma - Cacciatore di Demoni", enDescription = "Teaches you how to permanently enchant a piece of chest armor to reflect 9 damage back to the attacker when the bearer is struck in Melee.", description = "Ti insegna a incantare permanentemente un’armatura per il torso per riflettere 9 danni all’attaccante quando chi la indossa viene colpito in mischia." },
    [215141] = { enName = "Enchanted Sigil: Innovation", itName = "Formula: Incanta Arma - Cacciatore di Demoni", enDescription = "Teaches you how to conjure a sigil of innovation. ", description = "Ti insegna a evocare un sigillo dell’Innovazione." },
    [215149] = { enName = "Pattern: Gneuro-Linked Arcano-Filament Monocle", itName = "Modello: Stivali Foschi", enDescription = "Teaches you how to craft a Gneuro-Linked Arcano-Filament Monocle.", description = "Ti insegna a creare un Monocolo Gneurocollegato in Arcano-Filamento." },
    [215152] = { enName = "Pattern: Glowing Gneuro-Linked Cowl", itName = "Modello: Stivali Foschi", enDescription = "Teaches you how to craft a Glowing Gneuro-Linked Cowl.", description = "Ti insegna a creare un Cappuccio Gneurocollegato Luminoso." },
}
for itemID, entry in pairs(frequentItemDescriptions) do
    if ns.data.itemDescriptionOverrides[itemID] == nil then
        ns.data.itemDescriptionOverrides[itemID] = entry
